or-text);font-size:10px;font-weight:500;letter-spacing:1px;text-transform:uppercase;line-height:1.4;transition:background .2s,color .2s}.button:hover{background:var(--color-bg);color:var(--color-text)}.button--outline{background:transparent;color:var(--color-text)}.text-link{font-size:10px;text-transform:uppercase;letter-spacing:1px;padding-bottom:5px;border-bottom:1px solid currentColor}.rte p{margin-bottom:18px}.rte a{text-decoration:underline;text-underline-offset:4px}.rte h2,.rte h3{margin:32px 0 18px}.rte table{width:100%;border-collapse:collapse}.rte td,.rte th{padding:12px;border-bottom:1px solid var(--color-line)}.rte img{height:auto}.section-space{padding:var(--space-section) var(--page-margin)}.error{color:#963d35}.form-message{margin:14px 0;font-size:12px}dialog{border:0;margin:0;padding:0;background:var(--color-bg);color:var(--color-text);max-height:100dvh}dialog::backdrop{background:#0005}.dialog-top{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--color-line);padding:24px}.dialog-top h2{font-size:28px}.icon-close{font:300 28px/1 Arial;width:36px;height:36px;display:grid;place-items:center}.drawer{inset:0 0 0 auto;height:100dvh;width:min(500px,100%);max-width:100%}.drawer-body{padding:24px}.newsletter-input{display:flex;border-bottom:1px solid var(--color-line)}.newsletter-input input{flex:1;min-width:0;border:0;padding:16px 0}.newsletter-input button{padding:16px 0 16px 20px}.newsletter-consent{display:flex;gap:9px;text-align:left;font-size:10px;margin-top:18px}.newsletter-consent input{margin:3px 0 0}.newsletter-consent a{text-decoration:underline}.shopify-policy__container{max-width:760px!important;padding:64px 24px 100px!important}.shopify-policy__title{margin-bottom:42px!important}.shopify-policy__body{font-size:13px}.shopify-policy__body h2{margin-top:35px}.empty-state{text-align:center;padding:100px 20px}.empty-state h1{margin-bottom:24px}.pagination{display:flex;justify-content:center;gap:20px;padding:4